let zoneMap: Record<string, string> | null = null;

/** "Europe/Paris" -> "FR"; null when unknown. */
export function countryOfTimeZone(tz: unknown): string | null {
  if (!zoneMap) {
    const m: Record<string, string> = {};
    for (const part of ZONES.split(';')) {
      const i = part.indexOf(':');
      const area = part.slice(0, i);
      for (const pair of part.slice(i + 1).split(',')) {
        const j = pair.indexOf('=');
        m[area + '/' + pair.slice(0, j)] = pair.slice(j + 1);
      }
    }
    zoneMap = m;
  }
  const k = String(tz || '');
  return Object.prototype.hasOwnProperty.call(zoneMap, k) ? zoneMap[k] : null;
}

/** The country of this phone's time zone (Africa/Douala -> CM), or null. Never throws. */
export function countryOfZone(): string | null {
  try {
    return countryOfTimeZone(Intl.DateTimeFormat().resolvedOptions().timeZone);
  } catch {
    return null;
  }
}
